# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_УКГ1_148_2", r"$y=\frac1{(x-2)^{3}}$ при $x<2$: $y(1)=-1$, $y(1{,}5)=-8$, $y(1{,}9)=-1000$ — значения убывают при росте $x$ (функция $t^{3}$ возрастает и отрицательна, обратная величина $\frac1t$ убывает на $(-\infty;0)$); ключ «возрастает» неверен",
  k=r"убывает",
  dnew={0: (r"возрастает", r"Ученик решил, что $\frac1{t}$ при отрицательных $t$ ведёт себя как $t$; но $y(1)=-1>y(1{,}5)=-8$, то есть при росте $x$ значение уменьшается."),
        1: (r"постоянна", r"Ученик решил, что функция вида $\frac1{(x-2)^{3}}$ не зависит от $x$; но значения меняются: $y(1)=-1$, $y(1{,}5)=-8$."),
        2: (r"не определена", r"Ученик решил, что при $x<2$ знаменатель отрицателен и дробь не имеет смысла; но отрицательный знаменатель допустим, дробь определена при всех $x\ne2$.")})
E("G9_TB_УКГ2_193_1", r"$2y^{2}-xy+3$ при $y=3x+1$: $2(9x^{2}+6x+1)-x(3x+1)+3=18x^{2}+12x+2-3x^{2}-x+3=15x^{2}+11x+5$ (в ключе $9x$)",
  k=r"$15x^{2} + 11x + 5$",
  dnew={0: (r"$15x^{2} + 9x + 5$", r"Ученик записал произведение $x(3x+1)$ как $3x^{2}+3x$ и получил $12x-3x=9x$; верно $x(3x+1)=3x^{2}+x$, отсюда $12x-x=11x$."),
        1: (r"$15x^{2} + 15x + 5$", r"Ученик при раскрытии $-x(3x+1)$ получил $-3x^{2}+3x$ и прибавил его к $12x$, вместо $12x-x=11x$.")})
